<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use DateTimeImmutable;
use Override;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkMailGateway;

final class InMemoryMagicLinkMailGateway implements MagicLinkMailGateway
{
    /** @var array<array{email: string, url: string}> */
    public array $sent = [];

    #[Override]
    public function sendMagicLink(
        string $toEmail,
        string $userName,
        TenantRef $tenant,
        string $magicUrl,
        DateTimeImmutable $expiresAt,
    ): void {
        $this->sent[] = ['email' => $toEmail, 'url' => $magicUrl];
    }

    public function lastUrl(): ?string
    {
        if ($this->sent === []) {
            return null;
        }
        return end($this->sent)['url'];
    }

    public function count(): int
    {
        return count($this->sent);
    }
}
